import type { LucideIcon } from 'lucide-react'
import {
  BarChart2,
  Briefcase,
  CalendarDays,
  CreditCard,
  Image,
  Inbox,
  MessageSquare,
  Package,
  Megaphone,
  FileText,
  Sparkles,
  SunMedium,
  Users,
} from 'lucide-react'

export type NavRole = 'owner' | 'admin' | 'artist' | 'receptionist' | 'guest_artist'
export type PlanTier = 'solo' | 'studio' | 'pro' | 'enterprise'

/**
 * Static badge type displayed on the nav item.
 *  - count: resolved from dynamicBadge at render time (e.g. "4", "1.2k")
 *  - dot: small red circle (inventory alerts, urgent signals)
 *  - new: emerald outline "NEW" label
 */
export type BadgeType = 'count' | 'dot' | 'new'

/**
 * Which real-time count this item's badge should reflect.
 * Resolved server-side in layout.tsx and passed as dynamicBadges prop.
 */
export type DynamicBadgeKey = 'inbox' | 'calendar' | 'clients' | 'messages' | 'inventory'

export interface NavItem {
  label: string
  href: string
  icon: LucideIcon
  requiredRoles: NavRole[]
  requiredPlan?: PlanTier
  featureKey?: string
  /** Static badge type. For 'count' and 'dot', also set dynamicBadge. */
  badgeType?: BadgeType
  /** Which dynamic count this badge renders. badgeType must also be set. */
  dynamicBadge?: DynamicBadgeKey
  /** If set, this item is hidden when the user lacks this permission key */
  requiredPermission?: string
}

export interface NavGroup {
  /** null = unlabeled group (no SidebarGroupLabel rendered) */
  label: string | null
  items: NavItem[]
  condition?: 'always' | 'multi-location'
}

/**
 * S17 v2 sidebar — 4 groups matching the InkOS v2 artifact spec.
 *
 * Group 1 (unlabeled): Today / Inbox / Calendar / Messages
 * Group 2 STUDIO:      Clients / Team / Flash & Portfolio
 * Group 3 OPERATIONS:  Payments / Inventory / Forms / Analytics
 * Group 4 GROWTH:      AI / Marketing
 *
 * Settings moved to footer gear icon (SidebarUserFooter).
 * Commissions + Payroll consolidated into /payments?tab= (redirects in next.config.ts).
 *
 * Item count by role (owner/pro):
 *  owner/admin:    13 items
 *  artist:          8 items (Today, Inbox, Calendar, Messages, Clients, Portfolio, Payments, AI)
 *  receptionist:    9 items (Today, Inbox, Calendar, Messages, Clients, Team, Payments, Inventory, Forms)
 *  guest_artist:    4 items (Today, Inbox, Calendar, Messages)
 */
export const APP_NAV: NavGroup[] = [
  // ── UNLABELED TOP ─────────────────────────────────────────────────────────
  {
    label: null,
    items: [
      {
        label: 'Today',
        href: '/today',
        icon: SunMedium,
        requiredRoles: ['owner', 'admin', 'artist', 'receptionist', 'guest_artist'],
      },
      {
        label: 'Inbox',
        href: '/inbox',
        icon: Inbox,
        requiredRoles: ['owner', 'admin', 'artist', 'receptionist', 'guest_artist'],
        badgeType: 'count',
        dynamicBadge: 'inbox',
      },
      {
        label: 'Calendar',
        href: '/calendar',
        icon: CalendarDays,
        requiredRoles: ['owner', 'admin', 'artist', 'receptionist', 'guest_artist'],
        badgeType: 'count',
        dynamicBadge: 'calendar',
      },
      {
        label: 'Messages',
        href: '/messages',
        icon: MessageSquare,
        requiredRoles: ['owner', 'admin', 'artist', 'receptionist', 'guest_artist'],
      },
    ],
  },

  // ── STUDIO ────────────────────────────────────────────────────────────────
  {
    label: 'STUDIO',
    items: [
      {
        label: 'Clients',
        href: '/clients',
        icon: Users,
        requiredRoles: ['owner', 'admin', 'artist', 'receptionist'],
        badgeType: 'count',
        dynamicBadge: 'clients',
      },
      {
        // Tab host: Roster / Schedules / Guest Artists / Permissions
        // Route stays /artists — labelled "Team" per S13/S17
        label: 'Team',
        href: '/artists',
        icon: Briefcase,
        requiredRoles: ['owner', 'admin', 'receptionist'],
      },
      {
        label: 'Flash & Portfolio',
        href: '/portfolio',
        icon: Image,
        requiredRoles: ['owner', 'admin', 'artist'],
      },
    ],
  },

  // ── OPERATIONS ────────────────────────────────────────────────────────────
  {
    label: 'OPERATIONS',
    items: [
      {
        // Tab host: Transactions / Commissions / Payroll
        label: 'Payments',
        href: '/payments',
        icon: CreditCard,
        requiredRoles: ['owner', 'admin', 'artist'],
      },
      {
        label: 'Inventory',
        href: '/inventory',
        icon: Package,
        requiredRoles: ['owner', 'admin', 'receptionist'],
        requiredPlan: 'studio',
        featureKey: 'inventory',
        badgeType: 'dot',
        dynamicBadge: 'inventory',
      },
      {
        // Sidebar label "Forms" — route /consent-forms unchanged
        label: 'Forms',
        href: '/consent-forms',
        icon: FileText,
        requiredRoles: ['owner', 'admin', 'artist', 'receptionist'],
      },
      {
        // Sidebar label "Analytics" — route /reports unchanged
        label: 'Analytics',
        href: '/reports',
        icon: BarChart2,
        requiredRoles: ['owner', 'admin'],
        requiredPlan: 'studio',
        featureKey: 'analytics',
      },
    ],
  },

  // ── GROWTH ────────────────────────────────────────────────────────────────
  {
    label: 'GROWTH',
    items: [
      {
        // Sidebar label "AI" — route /ai-design unchanged
        label: 'AI',
        href: '/ai-design',
        icon: Sparkles,
        requiredRoles: ['owner', 'admin', 'artist'],
        requiredPlan: 'pro',
        featureKey: 'ai_design',
        badgeType: 'new',
      },
      {
        label: 'Marketing',
        href: '/marketing',
        icon: Megaphone,
        requiredRoles: ['owner', 'admin'],
        requiredPlan: 'studio',
        featureKey: 'marketing_basic',
      },
    ],
  },
]

'use client'

import Link from 'next/link'
import { usePathname, useRouter } from 'next/navigation'
import {
  SidebarGroup,
  SidebarGroupLabel,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
} from '@/components/ui/sidebar'
import { PlanBadge } from '@/components/shared/PlanBadge'
import type { NavGroup, DynamicBadgeKey } from '@/components/app/sidebar/nav-config'
import { hasFeature } from '@/lib/billing/feature-gate'
import type { PlanTier } from '@/lib/billing/feature-gate'
import { cn } from '@/lib/utils'

export type DynamicBadgeCounts = Partial<Record<DynamicBadgeKey, number>>

interface SidebarNavGroupProps {
  group: NavGroup
  plan: PlanTier
  isFirst?: boolean
  dynamicBadges?: DynamicBadgeCounts
}

/**
 * S17 — Updated for v2 sidebar:
 *  - Supports null label (unlabeled group skips <SidebarGroupLabel>)
 *  - Renders new badge types: count (gray pill), dot (red 6px circle), new (emerald outline)
 *  - Consumes dynamic badge counts from server-passed props
 *
 * Visual DNA (S13 tokens):
 *  - Item height: 32px (h-8)
 *  - Icons: 16px (size-4)
 *  - Icon→label gap: 8px (gap-2)
 *  - Label: 13px / font-weight 500
 *  - Section headers: 11px uppercase tracking-wider
 *  - Active state: full bg fill (bg-primary/10 text-primary) — Notion pattern
 */
export function SidebarNavGroup({ group, plan, isFirst, dynamicBadges = {} }: SidebarNavGroupProps) {
  const pathname = usePathname()
  const router = useRouter()

  return (
    <SidebarGroup className={cn('px-0', isFirst ? 'pt-0' : 'pt-4')}>
      {group.label !== null && (
        <SidebarGroupLabel className="mb-1 px-2.5 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground/50 group-data-[collapsible=icon]:hidden">
          {group.label}
        </SidebarGroupLabel>
      )}
      <SidebarMenu className="gap-0.5">
        {group.items.map((item) => {
          const isActive =
            item.href === '/today'
              ? pathname === item.href
              : pathname === item.href || pathname.startsWith(item.href + '/')

          const isGated =
            !!item.requiredPlan &&
            !hasFeature(plan, item.featureKey ?? item.requiredPlan)

          // Resolve dynamic badge count
          const dynamicCount = item.dynamicBadge !== undefined ? (dynamicBadges[item.dynamicBadge] ?? 0) : 0

          // Decide what badge to show (never show both plan badge and count badge)
          const showCountBadge = item.badgeType === 'count' && dynamicCount > 0 && !isGated
          const showDotBadge = item.badgeType === 'dot' && dynamicCount > 0 && !isGated
          const showNewBadge = item.badgeType === 'new' && !isGated

          function formatCount(n: number): string {
            if (n >= 1000) return `${(n / 1000).toFixed(1)}k`
            return String(n)
          }

          function handleClick() {
            if (isGated) {
              router.push('/settings/billing')
              return
            }
            router.push(item.href)
          }

          return (
            <SidebarMenuItem key={item.href}>
              <SidebarMenuButton
                render={isGated ? <button type="button" /> : <Link href={item.href} prefetch />}
                isActive={isActive}
                onClick={isGated ? handleClick : undefined}
                className={cn(
                  'group/item relative h-8 gap-2 rounded-md px-2.5 text-[13px] font-medium transition-all duration-150',
                  'text-sidebar-foreground/65 hover:bg-sidebar-accent/40 hover:text-sidebar-foreground',
                  'data-[active=true]:bg-primary/10 data-[active=true]:text-primary data-[active=true]:font-semibold',
                  isGated && 'opacity-60',
                )}
                tooltip={item.label}
              >
                <item.icon
                  className={cn(
                    '!h-4 !w-4 shrink-0 transition-opacity',
                    isActive ? 'opacity-100' : 'opacity-55 group-hover/item:opacity-80',
                  )}
                  aria-hidden="true"
                />
                <span className="truncate group-data-[collapsible=icon]:hidden">
                  {item.label}
                </span>

                {/* Plan badge — shown for gated items */}
                {isGated && item.requiredPlan && item.requiredPlan !== 'solo' && (
                  <PlanBadge
                    plan={item.requiredPlan}
                    className="ml-auto group-data-[collapsible=icon]:hidden"
                  />
                )}

                {/* Count badge — gray pill with number */}
                {showCountBadge && (
                  <span
                    className="ml-auto inline-flex min-w-[20px] items-center justify-center rounded-full bg-muted px-1.5 py-0.5 text-[10px] font-semibold tabular-nums text-muted-foreground group-data-[collapsible=icon]:hidden"
                    aria-label={`${dynamicCount} items`}
                  >
                    {formatCount(dynamicCount)}
                  </span>
                )}

                {/* Dot badge — 6px red circle for alerts */}
                {showDotBadge && (
                  <span
                    className="ml-auto flex h-2 w-2 shrink-0 rounded-full bg-destructive group-data-[collapsible=icon]:hidden"
                    aria-label="Alert"
                  />
                )}

                {/* New badge — emerald outline label */}
                {showNewBadge && (
                  <span
                    className="ml-auto inline-flex items-center rounded-sm border border-emerald-500/30 bg-emerald-500/10 px-1.5 py-0.5 text-[9px] font-semibold uppercase tracking-wide text-emerald-600 dark:text-emerald-400 group-data-[collapsible=icon]:hidden"
                  >
                    NEW
                  </span>
                )}
              </SidebarMenuButton>
            </SidebarMenuItem>
          )
        })}
      </SidebarMenu>
    </SidebarGroup>
  )
}

'use client'

import { Copy, ExternalLink } from 'lucide-react'
import { toast } from 'sonner'
import { cn } from '@/lib/utils'

interface BookingLinkWidgetProps {
  studioSlug: string
  className?: string
}

/**
 * S17 — Copyable booking link widget shown below the studio switcher.
 * Displays inkos.app/book/{slug} and copies to clipboard on click.
 */
export function BookingLinkWidget({ studioSlug, className }: BookingLinkWidgetProps) {
  const appUrl = process.env.NEXT_PUBLIC_APP_URL ?? 'https://inkos.app'
  const bookingUrl = `${appUrl}/book/${studioSlug}`
  const displayUrl = bookingUrl.replace(/^https?:\/\//, '')

  async function handleCopy() {
    try {
      await navigator.clipboard.writeText(bookingUrl)
      toast.success('Link copied')
    } catch {
      toast.error('Could not copy link')
    }
  }

  return (
    <div
      className={cn(
        'group/widget mx-2 mb-1 flex items-center gap-1.5 rounded-md border border-border/40 bg-muted/20 px-2 py-1.5 transition-colors hover:border-border/60 hover:bg-muted/40 group-data-[collapsible=icon]:hidden',
        className,
      )}
    >
      <ExternalLink className="h-3 w-3 shrink-0 text-muted-foreground/50" aria-hidden="true" />
      <span
        className="min-w-0 flex-1 truncate text-[11px] text-muted-foreground/70"
        title={displayUrl}
      >
        {displayUrl}
      </span>
      <button
        type="button"
        aria-label="Copy booking link"
        onClick={handleCopy}
        className="flex h-5 w-5 shrink-0 cursor-pointer items-center justify-center rounded opacity-0 transition-all hover:bg-muted/60 group-hover/widget:opacity-100 focus-visible:opacity-100 focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
      >
        <Copy className="h-3 w-3 text-muted-foreground/70" aria-hidden="true" />
      </button>
    </div>
  )
}

'use client'

import { useMemo } from 'react'
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarHeader,
} from '@/components/ui/sidebar'
import { SidebarNavGroup } from '@/components/app/sidebar/SidebarNavGroup'
import type { DynamicBadgeCounts } from '@/components/app/sidebar/SidebarNavGroup'
import { APP_NAV, type NavRole } from '@/components/app/sidebar/nav-config'
import { BookingLinkWidget } from '@/components/app/sidebar/BookingLinkWidget'
import { FavoritesPlaceholder } from '@/components/app/sidebar/FavoritesPlaceholder'
import { SidebarUserFooter } from '@/components/app/sidebar/SidebarUserFooter'
import { StudioSwitcher } from '@/components/shared/StudioSwitcher'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { StudioMembership } from '@/lib/context/active-studio'

interface AppSidebarProps {
  plan: PlanTier
  studioName: string
  studioLogoUrl?: string | null
  studioSlug: string
  role: NavRole
  locationCount: number
  /** Serialized from server — Set<string> → JSON array → passed as prop */
  permissionKeys?: string[]
  /** Dynamic badge counts from server (inbox, calendar, clients, inventory) */
  dynamicBadges?: DynamicBadgeCounts
  /** S15: all studio memberships — single item = no switcher rendered */
  allMemberships: StudioMembership[]
  /** S15: active studio id */
  currentStudioId: string
  /** User info for footer */
  userName: string
  userEmail: string
  userAvatarUrl?: string | null
  /** Callback to open CommandPalette */
  onOpenCommandPalette?: () => void
}

export function AppSidebar({
  plan,
  studioName,
  studioLogoUrl,
  studioSlug,
  role,
  locationCount,
  permissionKeys = [],
  dynamicBadges = {},
  allMemberships,
  currentStudioId,
  userName,
  userEmail,
  userAvatarUrl,
  onOpenCommandPalette,
}: AppSidebarProps) {
  const permissions = useMemo(() => new Set(permissionKeys), [permissionKeys])

  const navGroups = useMemo(() => {
    return APP_NAV
      .filter((group) => !(group.condition === 'multi-location' && locationCount <= 1))
      .map((group) => ({
        ...group,
        items: group.items.filter((item) => {
          if (!item.requiredRoles.includes(role)) return false
          if (item.requiredPermission && !permissions.has(item.requiredPermission)) return false
          return true
        }),
      }))
      .filter((group) => group.items.length > 0)
  }, [role, locationCount, permissions])

  return (
    <Sidebar collapsible="icon" className="border-r border-sidebar-border/60">
      {/* ── Brand header with ⌘K hint ─────────────────────────── */}
      <SidebarHeader className="border-b border-sidebar-border/60 px-3 py-2.5">
        <div className="flex items-center gap-2 group-data-[collapsible=icon]:justify-center">
          {studioLogoUrl ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img
              src={studioLogoUrl}
              alt={studioName}
              className="h-8 w-8 shrink-0 rounded-lg object-cover ring-1 ring-primary/20"
            />
          ) : (
            <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-gradient-to-br from-primary to-primary/80 text-primary-foreground shadow-[0_2px_8px_-2px_rgba(124,58,237,0.4)] ring-1 ring-primary/30">
              <span className="text-[11px] font-bold tracking-tight">IO</span>
            </div>
          )}
          <span className="truncate text-[13px] font-semibold leading-none tracking-tight text-sidebar-foreground group-data-[collapsible=icon]:hidden">
            InkOS
          </span>
          {/* ⌘K hint pill */}
          <button
            type="button"
            aria-label="Open command palette (⌘K)"
            onClick={onOpenCommandPalette}
            className="ml-auto flex h-5 shrink-0 items-center gap-0.5 rounded border border-border/50 bg-muted/30 px-1.5 text-[10px] font-mono text-muted-foreground/60 transition-colors hover:border-border hover:bg-muted/60 hover:text-muted-foreground group-data-[collapsible=icon]:hidden"
          >
            <span>⌘</span><span>K</span>
          </button>
        </div>

        {/* Studio switcher row */}
        <div className="mt-2 group-data-[collapsible=icon]:hidden">
          {allMemberships.length >= 2 ? (
            <StudioSwitcher
              currentStudioId={currentStudioId}
              allMemberships={allMemberships}
            />
          ) : (
            <div className="flex h-8 items-center gap-2 rounded-lg border border-border/40 bg-muted/20 px-2">
              <span className="truncate text-[13px] font-medium text-sidebar-foreground/80">
                {studioName}
              </span>
            </div>
          )}
        </div>

        {/* Booking link widget */}
        <BookingLinkWidget studioSlug={studioSlug} className="mt-1.5 mx-0" />
      </SidebarHeader>

      {/* ── Nav groups ────────────────────────────────────────── */}
      <SidebarContent className="gap-0 px-2 py-3">
        {navGroups.map((group, idx) => (
          <SidebarNavGroup
            key={group.label ?? '_unlabeled'}
            group={group}
            plan={plan}
            isFirst={idx === 0}
            dynamicBadges={dynamicBadges}
          />
        ))}

        {/* Favorites placeholder */}
        <FavoritesPlaceholder />
      </SidebarContent>

      {/* ── User footer ───────────────────────────────────────── */}
      <SidebarFooter className="p-0">
        <SidebarUserFooter
          userName={userName}
          userEmail={userEmail}
          userAvatarUrl={userAvatarUrl}
          role={role}
        />
      </SidebarFooter>
    </Sidebar>
  )
}

import { redirect } from 'next/navigation'
import { cookies } from 'next/headers'
import { createClient } from '@/lib/supabase/server'
import { SidebarProvider } from '@/components/ui/sidebar'
import { AppSidebar } from '@/components/app/sidebar/AppSidebar'
import { AppHeader } from '@/components/app/sidebar/AppHeader'
import { PermissionsProvider } from '@/lib/team/permissions-context'
import { getUserPermissions } from '@/lib/team/permissions'
import { StudioParamSync } from '@/components/shared/StudioParamSync'
import { getActiveStudio, NoStudioMembershipError } from '@/lib/context/active-studio'
import { getActiveLocation } from '@/lib/context/active-location'
import type { DynamicBadgeCounts } from '@/components/app/sidebar/SidebarNavGroup'

interface AppLayoutProps {
  children: React.ReactNode
}

export default async function AppLayout({ children }: AppLayoutProps) {
  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (!user) {
    redirect('/login')
  }

  // S15: resolve active studio via cookie (replaces .limit(1).single() pattern)
  let activeStudio: Awaited<ReturnType<typeof getActiveStudio>>
  try {
    activeStudio = await getActiveStudio()
  } catch (err) {
    if (err instanceof NoStudioMembershipError) {
      redirect('/onboarding')
    }
    redirect('/onboarding')
  }

  const { studioId, studio, role, plan, allMemberships } = activeStudio

  // S15: resolve active location (depends on studioId — sequential, not Promise.all)
  const activeLocation = await getActiveLocation(studioId, role)

  // Fetch user profile + dynamic badge counts in parallel
  const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString()
  const oneDayAgo = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString()
  const todayStart = new Date()
  todayStart.setHours(0, 0, 0, 0)
  const todayEnd = new Date()
  todayEnd.setHours(23, 59, 59, 999)

  const [
    profileResult,
    inboxPendingRes,
    inboxConsentRes,
    inboxWaitlistRes,
    calendarTodayRes,
    clientsTotalRes,
    inventoryLowRes,
  ] = await Promise.all([
    supabase
      .from('profiles')
      .select('full_name, avatar_url')
      .eq('id', user.id)
      .single(),
    // Inbox: pending_confirmation bookings
    supabase
      .from('bookings')
      .select('id', { count: 'exact', head: true })
      .eq('studio_id', studioId)
      .eq('status', 'pending_confirmation'),
    // Inbox: unreviewed consent submissions in last 7d
    supabase
      .from('consent_submissions')
      .select('id', { count: 'exact', head: true })
      .eq('studio_id', studioId)
      .gte('created_at', sevenDaysAgo)
      .is('reviewed_at', null),
    // Inbox: waitlist signups in last 24h
    supabase
      .from('waitlist')
      .select('id', { count: 'exact', head: true })
      .eq('studio_id', studioId)
      .gte('created_at', oneDayAgo),
    // Calendar: bookings scheduled today
    supabase
      .from('bookings')
      .select('id', { count: 'exact', head: true })
      .eq('studio_id', studioId)
      .gte('scheduled_at', todayStart.toISOString())
      .lte('scheduled_at', todayEnd.toISOString()),
    // Clients: total for studio
    supabase
      .from('clients')
      .select('id', { count: 'exact', head: true })
      .eq('studio_id', studioId),
    // Inventory: low stock items
    supabase
      .from('inventory_items')
      .select('id', { count: 'exact', head: true })
      .eq('studio_id', studioId)
      .or('low_stock_alert.eq.true,quantity.lte.reorder_threshold'),
  ])

  // Permissions
  const permissionsSet =
    studioId && user ? await getUserPermissions(studioId, user.id) : new Set<string>()
  const permissionKeys = [...permissionsSet]

  // Sidebar state from cookie
  const cookieStore = await cookies()
  const sidebarOpen = cookieStore.get('sidebar_state')?.value !== 'false'

  const profile = profileResult.data
  const userName = profile?.full_name ?? user.email?.split('@')[0] ?? 'You'
  const userEmail = user.email ?? ''
  const userAvatarUrl = profile?.avatar_url ?? null
  const studioName = studio.name
  const studioLogoUrl = studio.logo_url ?? null
  const studioSlug = studio.slug

  // Compute dynamic badge counts (graceful: null count → 0)
  const inboxCount =
    (inboxPendingRes.count ?? 0) +
    (inboxConsentRes.count ?? 0) +
    (inboxWaitlistRes.count ?? 0)

  const dynamicBadges: DynamicBadgeCounts = {
    inbox: inboxCount,
    calendar: calendarTodayRes.count ?? 0,
    clients: clientsTotalRes.count ?? 0,
    inventory: inventoryLowRes.count ?? 0,
  }

  return (
    <PermissionsProvider permissionKeys={permissionKeys}>
      {/* S15: StudioParamSync handles ?studio=X deep links — renders null */}
      <StudioParamSync currentStudioId={studioId} />
      <SidebarProvider defaultOpen={sidebarOpen} className="h-svh">
        <AppSidebar
          locationCount={activeLocation.allLocations.length}
          plan={plan}
          studioName={studioName}
          studioLogoUrl={studioLogoUrl}
          studioSlug={studioSlug}
          role={role}
          permissionKeys={permissionKeys}
          dynamicBadges={dynamicBadges}
          allMemberships={allMemberships}
          currentStudioId={studioId}
          userName={userName}
          userEmail={userEmail}
          userAvatarUrl={userAvatarUrl}
        />
        <AppHeader
          studioName={studioName}
          userName={userName}
          userEmail={userEmail}
          userAvatarUrl={userAvatarUrl}
          role={role}
          plan={plan}
          allMemberships={allMemberships}
          currentStudioId={studioId}
          currentLocationId={activeLocation.locationId}
          allLocations={activeLocation.allLocations}
          permissionKeys={permissionKeys}
        >
          {children}
        </AppHeader>
      </SidebarProvider>
    </PermissionsProvider>
  )
}

