import { useEffect, useState } from 'react'
import { CalendarDays, CreditCard, DollarSign, Users } from 'lucide-react'
import { Typography } from '@/components/ui/typography'
import { KpiCard } from '@/components/shared/KpiCard'
import { KpiCardSkeleton } from '@/components/shared/KpiCardSkeleton'
import { ActivityFeed } from '@/components/shared/ActivityFeed'
import { AlertsCard } from '@/components/shared/AlertsCard'
import { InventoryAlertsCard } from '@/components/inventory/InventoryAlertsCard'
import { GettingStartedCard } from '@/components/dashboard/GettingStartedCard'
import { TodayAgendaWidget } from '@/components/dashboard/TodayAgendaWidget'
import { QuickActionsRow } from '@/components/dashboard/QuickActionsRow'
import { EmptyDashboardState } from '@/components/dashboard/EmptyDashboardState'
import { useDashboardKpis } from '@/hooks/dashboard/use-dashboard-kpis'
import { useTodayAgenda } from '@/hooks/dashboard/use-today-agenda'
import { useRecentActivity } from '@/hooks/dashboard/use-recent-activity'
import { useInventoryAlerts } from '@/hooks/dashboard/use-inventory-alerts'
import { useDashboardAlerts } from '@/hooks/dashboard/use-dashboard-alerts'
import { useRouter } from 'next/navigation'
import type { GettingStartedCounts } from '@/components/dashboard/GettingStartedCard'

interface TodayClientProps {
  firstName: string
  studioName: string
  hasStudio: boolean
  studioId: string | null
  gettingStartedCounts: GettingStartedCounts
}

function formatDate(): string {
  return new Date().toLocaleDateString('en-US', {
    weekday: 'long',
    month: 'long',
    day: 'numeric',
  })
}

export function TodayClient({
  firstName,
  studioName,
  hasStudio,
  studioId,
  gettingStartedCounts,
}: TodayClientProps) {
  const router = useRouter()
  const kpisQuery = useDashboardKpis(hasStudio)
  const agendaQuery = useTodayAgenda(hasStudio)
  const activityQuery = useRecentActivity(hasStudio)
  const inventoryAlertsQuery = useInventoryAlerts(hasStudio)
  const alertsQuery = useDashboardAlerts(hasStudio)

  const kpis = kpisQuery.data
  const kpisLoading = kpisQuery.isLoading || kpisQuery.isFetching

  const [dismissedIds, setDismissedIds] = useState<string[]>([])

  const [checklistDismissed, setChecklistDismissed] = useState(false)
  useEffect(() => {
    setChecklistDismissed(
      localStorage.getItem('inkos:getting-started:dismissed') === '1',
    )
  }, [])

  // N shortcut — new appointment
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement
      const tag = target.tagName
      if (
        tag === 'INPUT' ||
        tag === 'TEXTAREA' ||
        tag === 'SELECT' ||
        target.isContentEditable
      )
        return
      if (e.key === 'n' || e.key === 'N') {
        e.preventDefault()
        router.push('/appointments/new')
      }
    }
    window.addEventListener('keydown', handler)
    return () => window.removeEventListener('keydown', handler)
  }, [router])

  const visibleAlerts = (alertsQuery.data ?? []).filter(
    (a) => !dismissedIds.includes(a.id),
  )

  const showEmptyState =
    checklistDismissed && gettingStartedCounts.bookings === 0

  const revenueMtd = kpis?.revenueMtd ?? 0
  const revenueMtdDelta = kpis?.revenueMtdDelta ?? '0%'
  const apptTodayCount = kpis?.apptTodayCount ?? 0
  const apptTodayCompleted = kpis?.apptTodayCompleted ?? 0
  const apptTodayPending = kpis?.apptTodayPending ?? 0
  const newClientsMtd = kpis?.newClientsMtd ?? 0
  const newClientsMtdDelta = kpis?.newClientsMtdDelta ?? '0%'
  const pendingDepositsTotal = kpis?.pendingDepositsTotal ?? 0
  const pendingDepositsCount = kpis?.pendingDepositsCount ?? 0
  const pendingDepositsDelta = kpis?.pendingDepositsDelta ?? '0%'

  const agendaAppointments = agendaQuery.data ?? []
  const totalToday = agendaAppointments.length

  return (
    <div className="min-h-full bg-[var(--color-page-bg)]">
      <div className="mx-auto max-w-[1440px] space-y-6 px-4 pb-10 pt-6 sm:px-6 lg:px-8">

        {/* ── Header ── */}
        <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
          <div>
            <p className="mb-0.5 text-xs font-medium uppercase tracking-[0.08em] text-muted-foreground">
              {studioName}
            </p>
            <Typography variant="h1" className="text-foreground">
              Your day,{' '}
              <span className="text-primary">{firstName}</span>
            </Typography>
            <p className="mt-0.5 text-sm text-muted-foreground">{formatDate()}</p>
          </div>
        </div>

        {/* ── Quick actions ── */}
        <QuickActionsRow />

        {/* ── Getting started checklist ── */}
        <GettingStartedCard counts={gettingStartedCounts} />

        {showEmptyState ? (
          <EmptyDashboardState />
        ) : (
          <>
            {/* ── KPI row ── */}
            <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
              {kpisLoading ? (
                Array.from({ length: 4 }).map((_, i) => <KpiCardSkeleton key={i} />)
              ) : (
                <>
                  <KpiCard
                    label="Revenue MTD"
                    value={revenueMtd}
                    formatter={(n) =>
                      n >= 100_000
                        ? `$${(n / 100_000).toFixed(1)}k`
                        : `$${(n / 100).toLocaleString()}`
                    }
                    delta={revenueMtdDelta}
                    trend={revenueMtdDelta.startsWith('+') ? 'up' : 'down'}
                    subtextLabel="vs last month"
                    {...(kpis?.revenueDailyLast30 !== undefined ? { sparkline: kpis.revenueDailyLast30 } : {})}
                    icon={DollarSign}
                    accentVar="var(--color-status-completed)"
                    hoverVariant="lift"
                    index={0}
                  />
                  <div
                    role="link"
                    tabIndex={0}
                    onClick={() =>
                      document
                        .getElementById('today-agenda')
                        ?.scrollIntoView({ behavior: 'smooth' })
                    }
                    onKeyDown={(e) => {
                      if (e.key === 'Enter') {
                        document
                          .getElementById('today-agenda')
                          ?.scrollIntoView({ behavior: 'smooth' })
                      }
                    }}
                    className="cursor-pointer"
                    aria-label="Scroll to today's agenda"
                  >
                    <KpiCard
                      label="Appointments Today"
                      value={apptTodayCount}
                      subtextLabel={`${apptTodayCompleted} completed · ${apptTodayPending} pending`}
                      icon={CalendarDays}
                      trend="neutral"
                      accentVar="var(--color-primary)"
                      hoverVariant="lift"
                      index={1}
                    />
                  </div>
                  <KpiCard
                    label="New Clients MTD"
                    value={newClientsMtd}
                    delta={newClientsMtdDelta}
                    trend={newClientsMtdDelta.startsWith('+') ? 'up' : 'down'}
                    subtextLabel="vs last month"
                    {...(kpis?.newClientsDailyLast30 !== undefined ? { sparkline: kpis.newClientsDailyLast30 } : {})}
                    icon={Users}
                    accentVar="var(--color-accent-foreground)"
                    hoverVariant="lift"
                    index={2}
                  />
                  <KpiCard
                    label="Pending Deposits"
                    value={pendingDepositsTotal}
                    formatter={(n) =>
                      n >= 100_000
                        ? `$${(n / 100_000).toFixed(1)}k`
                        : `$${(n / 100).toLocaleString()}`
                    }
                    delta={pendingDepositsDelta}
                    trend={pendingDepositsCount > 0 ? 'up' : 'down'}
                    invertTrend
                    subtextLabel={`${pendingDepositsCount} booking${pendingDepositsCount !== 1 ? 's' : ''}`}
                    icon={CreditCard}
                    accentVar="var(--color-warning)"
                    hoverVariant="lift"
                    index={3}
                  />
                </>
              )}
            </div>

            {/* ── Agenda + Activity ── */}
            <div className="grid grid-cols-1 gap-4 lg:grid-cols-12">
              <div className="lg:col-span-8">
                <TodayAgendaWidget
                  appointments={agendaAppointments}
                  totalToday={totalToday}
                  loading={agendaQuery.isLoading}
                />
              </div>
              <div className="lg:col-span-4">
                <ActivityFeed
                  events={activityQuery.data ?? []}
                  loading={activityQuery.isLoading}
                  {...(studioId !== null ? { studioId } : {})}
                />
              </div>
            </div>

            {/* ── Alerts ── */}
            <div className="grid grid-cols-1 gap-4">
              <AlertsCard
                alerts={visibleAlerts}
                loading={alertsQuery.isLoading}
                onDismiss={(id) =>
                  setDismissedIds((prev) => [...prev, id])
                }
              />
              {inventoryAlertsQuery.data != null && (
                <InventoryAlertsCard
                  openAlertsCount={inventoryAlertsQuery.data.open_alerts_count}
                  itemsBelowThreshold={inventoryAlertsQuery.data.items_below_threshold}
                  loading={inventoryAlertsQuery.isLoading}
                />
              )}
            </div>
          </>
        )}

      </div>
    </div>
  )
}

'use client'

import { useState } from 'react'
import Link from 'next/link'
import {
  CheckCircle2,
  Clock,
  FileText,
  Inbox,
  UserPlus,
} from 'lucide-react'
import { format, formatDistanceToNow } from 'date-fns'
import { Button } from '@/components/ui/button'
import { PageTabs } from '@/components/shared/PageTabs'
import { EmptyState } from '@/components/shared/EmptyState'
import { PageHeader } from '@/components/shared/PageHeader'
import { cn } from '@/lib/utils'
import type { NavRole } from '@/components/app/sidebar/nav-config'
import type { PlanTier } from '@/lib/billing/feature-gate'

export type InboxItemType = 'deposit' | 'form' | 'client' | 'waitlist'

export interface InboxItem {
  id: string
  type: InboxItemType
  title: string
  subtitle: string
  actionLabel: string
  actionHref: string
  timestamp: string
}

interface InboxClientProps {
  items: InboxItem[]
  currentPlan: PlanTier
  currentRole: NavRole
}

const TABS = [
  { key: 'all', label: 'All', href: '/inbox', hidden: undefined },
  { key: 'deposits', label: 'Deposits', href: '/inbox?tab=deposits' },
  { key: 'forms', label: 'Forms', href: '/inbox?tab=forms' },
  { key: 'clients', label: 'Clients', href: '/inbox?tab=clients' },
]

function itemIcon(type: InboxItemType) {
  switch (type) {
    case 'deposit': return <CheckCircle2 className="h-4 w-4 text-amber-500" aria-hidden="true" />
    case 'form': return <FileText className="h-4 w-4 text-blue-500" aria-hidden="true" />
    case 'client': return <UserPlus className="h-4 w-4 text-emerald-500" aria-hidden="true" />
    case 'waitlist': return <Clock className="h-4 w-4 text-purple-500" aria-hidden="true" />
  }
}

function itemBg(type: InboxItemType) {
  switch (type) {
    case 'deposit': return 'bg-amber-500/10'
    case 'form': return 'bg-blue-500/10'
    case 'client': return 'bg-emerald-500/10'
    case 'waitlist': return 'bg-purple-500/10'
  }
}

interface InboxRowProps {
  item: InboxItem
}

function InboxRow({ item }: InboxRowProps) {
  const ts = new Date(item.timestamp)
  const isRecent = Date.now() - ts.getTime() < 24 * 60 * 60 * 1000

  return (
    <div className="flex items-center gap-3 rounded-lg border border-border/40 bg-card px-4 py-3 transition-colors hover:border-border/70 hover:bg-muted/20">
      <div className={cn('flex h-8 w-8 shrink-0 items-center justify-center rounded-full', itemBg(item.type))}>
        {itemIcon(item.type)}
      </div>
      <div className="min-w-0 flex-1">
        <p className="truncate text-[13px] font-medium text-foreground">{item.title}</p>
        <p className="truncate text-[12px] text-muted-foreground">{item.subtitle}</p>
      </div>
      <time
        dateTime={item.timestamp}
        className="shrink-0 text-[11px] text-muted-foreground/60"
        title={format(ts, 'PPpp')}
      >
        {isRecent ? formatDistanceToNow(ts, { addSuffix: true }) : format(ts, 'MMM d')}
      </time>
      <Button
        asChild
        variant="outline"
        size="sm"
        className="shrink-0 text-[12px]"
      >
        <Link href={item.actionHref}>{item.actionLabel}</Link>
      </Button>
    </div>
  )
}

export function InboxClient({ items, currentPlan, currentRole }: InboxClientProps) {
  const [activeTab, setActiveTab] = useState<string>('all')

  const filteredItems = activeTab === 'all'
    ? items
    : items.filter((item) => {
        if (activeTab === 'deposits') return item.type === 'deposit'
        if (activeTab === 'forms') return item.type === 'form'
        if (activeTab === 'clients') return item.type === 'client' || item.type === 'waitlist'
        return true
      })

  const tabs = TABS.map((t) => ({
    ...t,
    badge: t.key === 'all' ? (items.length > 0 ? items.length : undefined) : undefined,
  }))

  return (
    <div className="flex min-h-full flex-col bg-[var(--color-page-bg)]">
      <PageHeader
        title="Inbox"
        description="Action items that need your attention"
      />

      <div className="px-6">
        <PageTabs
          tabs={tabs}
          activeKey={activeTab}
          currentPlan={currentPlan}
          currentRole={currentRole}
          className="mb-4"
        />
      </div>

      {/* Item list */}
      <div className="flex-1 space-y-2 px-6 pb-8">
        {filteredItems.length === 0 ? (
          <EmptyState
            icon={Inbox}
            title="Inbox is clear"
            description={
              activeTab === 'all'
                ? "You're all caught up. New action items appear here automatically."
                : "No items in this category right now."
            }
          />
        ) : (
          filteredItems.map((item) => (
            <InboxRow key={item.id} item={item} />
          ))
        )}
      </div>
    </div>
  )
}

import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { createClient } from '@/lib/supabase/server'
import { getActiveStudio, NoStudioMembershipError } from '@/lib/context/active-studio'
import { InboxClient } from '@/components/inbox/InboxClient'
import type { InboxItem, InboxItemType } from '@/components/inbox/InboxClient'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { NavRole } from '@/components/app/sidebar/nav-config'

export const metadata: Metadata = {
  title: 'Inbox — InkOS',
}

export default async function InboxPage() {
  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (!user) redirect('/login')

  let activeStudio: Awaited<ReturnType<typeof getActiveStudio>>
  try {
    activeStudio = await getActiveStudio()
  } catch (err) {
    if (err instanceof NoStudioMembershipError) redirect('/onboarding')
    redirect('/onboarding')
  }

  const { studioId, role, plan } = activeStudio
  const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString()
  const oneDayAgo = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString()

  // Fetch 4 signal sources in parallel
  const [
    pendingBookingsRes,
    consentSubmissionsRes,
    waitlistRes,
    newClientsRes,
  ] = await Promise.all([
    supabase
      .from('bookings')
      .select('id, client_id, clients(first_name, last_name), created_at')
      .eq('studio_id', studioId)
      .eq('status', 'pending_confirmation')
      .order('created_at', { ascending: false })
      .limit(50),
    supabase
      .from('consent_submissions')
      .select('id, client_id, template_id, created_at')
      .eq('studio_id', studioId)
      .gte('created_at', sevenDaysAgo)
      .is('reviewed_at', null)
      .order('created_at', { ascending: false })
      .limit(50),
    supabase
      .from('waitlist')
      .select('id, first_name, last_name, email, created_at')
      .eq('studio_id', studioId)
      .gte('created_at', oneDayAgo)
      .order('created_at', { ascending: false })
      .limit(50),
    supabase
      .from('clients')
      .select('id, first_name, last_name, created_at')
      .eq('studio_id', studioId)
      .gte('created_at', sevenDaysAgo)
      .order('created_at', { ascending: false })
      .limit(20),
  ])

  // Normalize into InboxItem[]
  const items: InboxItem[] = []

  // Pending bookings → deposit confirmation
  for (const booking of pendingBookingsRes.data ?? []) {
    const client = (booking.clients as { first_name: string; last_name: string } | null)
    const clientName = client ? `${client.first_name} ${client.last_name}` : 'Client'
    items.push({
      id: `booking-${booking.id}`,
      type: 'deposit' as InboxItemType,
      title: `Deposit confirmation needed`,
      subtitle: `${clientName} — booking pending`,
      actionLabel: 'Confirm',
      actionHref: `/bookings/${booking.id}`,
      timestamp: booking.created_at,
    })
  }

  // Unreviewed consent submissions
  for (const sub of consentSubmissionsRes.data ?? []) {
    items.push({
      id: `consent-${sub.id}`,
      type: 'form' as InboxItemType,
      title: `Consent form submitted`,
      subtitle: `Review required`,
      actionLabel: 'Review',
      actionHref: `/consent-forms/submissions/${sub.id}`,
      timestamp: sub.created_at,
    })
  }

  // Waitlist signups
  for (const entry of waitlistRes.data ?? []) {
    const name =
      entry.first_name && entry.last_name
        ? `${entry.first_name} ${entry.last_name}`
        : (entry.email ?? 'New signup')
    items.push({
      id: `waitlist-${entry.id}`,
      type: 'waitlist' as InboxItemType,
      title: `New waitlist signup`,
      subtitle: name,
      actionLabel: 'Reply',
      actionHref: `/clients`,
      timestamp: entry.created_at,
    })
  }

  // New clients without consent form — sample from recent new clients
  for (const client of newClientsRes.data ?? []) {
    items.push({
      id: `client-${client.id}`,
      type: 'client' as InboxItemType,
      title: `New client added`,
      subtitle: `${client.first_name} ${client.last_name}`,
      actionLabel: 'View',
      actionHref: `/clients/${client.id}`,
      timestamp: client.created_at,
    })
  }

  // Sort by timestamp descending
  items.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())

  return (
    <InboxClient
      items={items}
      currentPlan={plan as PlanTier}
      currentRole={role as NavRole}
    />
  )
}

'use client'

import { useState } from 'react'
import { MessageSquare } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { toast } from 'sonner'

/**
 * S17 — Polished coming-soon empty state for /messages.
 * "Notify me" posts to /api/feature-interest (feature='messages').
 */
export function MessagesComingSoon() {
  const [loading, setLoading] = useState(false)
  const [notified, setNotified] = useState(false)

  async function handleNotify() {
    setLoading(true)
    try {
      await fetch('/api/feature-interest', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ feature: 'messages' }),
      })
      setNotified(true)
      toast.success("We'll let you know when Messages ships")
    } catch {
      toast.error('Something went wrong. Try again.')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="flex min-h-[60vh] flex-col items-center justify-center px-6 text-center">
      <div className="mb-6 flex h-16 w-16 items-center justify-center rounded-2xl bg-primary/10">
        <MessageSquare className="h-8 w-8 text-primary" aria-hidden="true" />
      </div>
      <h1 className="mb-2 text-2xl font-bold tracking-tight text-foreground">
        Client messaging is coming soon
      </h1>
      <p className="mb-1 max-w-md text-sm text-muted-foreground">
        Threaded SMS + email chat with clients — track every conversation in one inbox.
      </p>
      <p className="mb-8 text-xs text-muted-foreground/60">
        Coming in Sprint S19
