import { redirect } from 'next/navigation'
import { createClient } from '@/lib/supabase/server'
import { hasFeature } from '@/lib/billing/feature-gate'
import type { PlanTier } from '@/lib/billing/feature-gate'
import { getUserPermissions } from '@/lib/team/permissions'
import { UpgradeGatePageBlock } from '@/components/billing/UpgradeGate'
import { CommissionsHub } from '@/components/commissions/CommissionsHub'

/**
 * S17 — Commissions tab for the /payments tab host (server component).
 * Extracted from app/(app)/commissions/page.tsx.
 */
export async function CommissionsTab() {
  const supabase = await createClient()

  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (!user) redirect('/login')

  const { data: member } = await supabase
    .from('studio_members')
    .select('role, studio_id')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()

  if (!member) redirect('/onboarding')

  const studioId = member.studio_id
  const role = member.role as string
  const isArtist = role === 'artist' || role === 'guest_artist'

  let plan: PlanTier = 'solo'
  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', studioId)
    .eq('status', 'active')
    .maybeSingle()
  if (sub?.plan_tier) plan = sub.plan_tier as PlanTier

  if (!hasFeature(plan, 'commissions')) {
    return (
      <div className="flex flex-1 items-center justify-center p-8">
        <UpgradeGatePageBlock
          requiredPlan="studio"
          feature="Commissions"
          description="Track, approve, and pay artist commissions with automated rule-based calculations. Upgrade to the Studio plan to unlock this feature."
        />
      </div>
    )
  }

  const permissionsSet = await getUserPermissions(studioId, user.id)
  const isOwner = role === 'owner'
  const canApprove =
    isOwner ||
    permissionsSet.has('commissions.approve') ||
    permissionsSet.has('admin.all')
  const canManage =
    isOwner ||
    permissionsSet.has('commissions.manage') ||
    permissionsSet.has('admin.all')

  let artistId: string | undefined
  if (isArtist) {
    const { data: artistRow } = await supabase
      .from('artists')
      .select('id')
      .eq('studio_id', studioId)
      .eq('profile_id', user.id)
      .maybeSingle()
    artistId = artistRow?.id ?? undefined
  }

  return (
    <CommissionsHub
      studioId={studioId}
      isArtist={isArtist}
      {...(artistId !== undefined ? { artistId } : {})}
      canApprove={canApprove}
      canManage={canManage}
      isOwner={isOwner}
    />
  )
}

