export const metadata: Metadata = {
  title: 'Payments — InkOS',
}

const VALID_TABS = ['transactions', 'commissions', 'payroll'] as const
type TabKey = (typeof VALID_TABS)[number]

interface SearchParams {
  tab?: string
}

function resolveTab(searchParams: SearchParams, role: NavRole): TabKey {
  const requested = searchParams.tab as TabKey | undefined
  if (requested && VALID_TABS.includes(requested)) {
    // Artists can only access commissions tab
    if (role === 'artist' && requested !== 'commissions') {
      return 'commissions'
    }
    return requested
  }
  // Default tab by role
  if (role === 'artist') return 'commissions'
  return 'transactions'
}

const PAYMENT_TABS: PageTab[] = [
  {
    key: 'transactions',
    label: 'Transactions',
    href: '/payments?tab=transactions',
    hidden: (role) => role === 'artist',
  },
  {
    key: 'commissions',
    label: 'Commissions',
    href: '/payments?tab=commissions',
    gated: 'studio',
    hidden: (role) => role === 'receptionist',
  },
  {
    key: 'payroll',
    label: 'Payroll',
    href: '/payments?tab=payroll',
    gated: 'pro',
    hidden: (role) => role === 'artist' || role === 'receptionist',
  },
]

const TabSkeleton = () => (
  <div className="p-6 space-y-4">
    <Skeleton className="h-8 w-32" />
    <Skeleton className="h-4 w-64" />
    <div className="space-y-2">
      {Array.from({ length: 8 }).map((_, i) => (
        <Skeleton key={i} className="h-12 w-full rounded-lg" />
      ))}
    </div>
  </div>
)

export default async function PaymentsPage({
  searchParams,
}: {
  searchParams: Promise<SearchParams>
}) {
  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (!user) redirect('/login')

  let activeStudio: Awaited<ReturnType<typeof getActiveStudio>>
  try {
    activeStudio = await getActiveStudio()
  } catch (err) {
    if (err instanceof NoStudioMembershipError) redirect('/onboarding')
    redirect('/onboarding')
  }

  const { role, plan } = activeStudio
  const resolvedParams = await searchParams
  const activeTab = resolveTab(resolvedParams, role as NavRole)

  return (
    <div className="flex min-h-full flex-col bg-[var(--color-page-bg)]">
      <PageHeader
        title="Payments"
        description="Transactions, commissions, and payroll in one place"
      />

      <div className="px-6">
        <PageTabs
          tabs={PAYMENT_TABS}
          activeKey={activeTab}
          currentPlan={plan as PlanTier}
          currentRole={role as NavRole}
          className="mb-0"
        />
      </div>

      <div className="flex-1">
        {activeTab === 'transactions' && (
          <Suspense fallback={<TabSkeleton />}>
            <TransactionsTab />
          </Suspense>
        )}
        {activeTab === 'commissions' && (
          <Suspense fallback={<TabSkeleton />}>
            <CommissionsTab />
          </Suspense>
        )}
        {activeTab === 'payroll' && (
          <Suspense fallback={<TabSkeleton />}>
            <PayrollTab />
          </Suspense>
        )}
      </div>
    </div>
  )
}

