'use client'

import { useCallback, useEffect, useMemo, useState } from 'react'
import { usePathname, useRouter } from 'next/navigation'
import { LogOut, Menu, X } from 'lucide-react'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import { Button } from '@/components/ui/button'
import { ScrollArea } from '@/components/ui/scroll-area'
import { Sheet, SheetContent } from '@/components/ui/sheet'
import { cn } from '@/lib/utils'
import { APP_NAV, type NavItem, type NavRole } from '@/components/app/sidebar/nav-config'
import { PlanBadge } from '@/components/shared/PlanBadge'
import { StudioSwitcher } from '@/components/shared/StudioSwitcher'
import { LocationSwitcher } from '@/components/shared/LocationSwitcher'
import { BookingLinkWidget } from '@/components/app/sidebar/BookingLinkWidget'
import { hasFeature } from '@/lib/billing/feature-gate'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { StudioMembership } from '@/lib/context/active-studio'
import type { LocationRow } from '@/lib/context/active-location'
import type { DynamicBadgeCounts } from '@/components/app/sidebar/SidebarNavGroup'

interface MobileNavProps {
  userName: string
  userEmail: string
  userAvatarUrl: string | null | undefined
  studioName: string
  studioSlug?: string
  role: NavRole
  locationCount: number
  permissionKeys: string[]
  plan?: PlanTier
  dynamicBadges?: DynamicBadgeCounts
  onSignOut: () => void
  open?: boolean
  onOpenChange?: (open: boolean) => void
  allMemberships: StudioMembership[]
  currentStudioId: string
  currentLocationId: string | null
  allLocations: LocationRow[]
}

function getInitials(name: string): string {
  return name
    .split(' ')
    .slice(0, 2)
    .map((n) => n[0])
    .join('')
    .toUpperCase()
}

interface MobileNavItemProps {
  item: NavItem
  onNavigate: () => void
  isActive: boolean
  plan: PlanTier
  dynamicBadges: DynamicBadgeCounts
}

function MobileNavItem({ item, onNavigate, isActive, plan, dynamicBadges }: MobileNavItemProps) {
  const Icon = item.icon
  const router = useRouter()

  const isGated =
    !!item.requiredPlan &&
    !hasFeature(plan, item.featureKey ?? item.requiredPlan)

  const dynamicCount = item.dynamicBadge !== undefined ? (dynamicBadges[item.dynamicBadge] ?? 0) : 0
  const showCountBadge = item.badgeType === 'count' && dynamicCount > 0 && !isGated
  const showDotBadge = item.badgeType === 'dot' && dynamicCount > 0 && !isGated
  const showNewBadge = item.badgeType === 'new' && !isGated

  function formatCount(n: number): string {
    if (n >= 1000) return `${(n / 1000).toFixed(1)}k`
    return String(n)
  }

  function handleClick() {
    if (isGated) {
      onNavigate()
      router.push('/settings/subscription/billing')
      return
    }
    onNavigate()
    router.push(item.href)
  }

  return (
    <button
      type="button"
      className={cn(
        'flex w-full min-h-[44px] items-center gap-2.5 rounded-lg px-2.5 text-[13px] font-medium transition-colors text-left',
        isActive
          ? 'bg-accent text-accent-foreground'
          : 'text-muted-foreground hover:bg-muted/50 hover:text-foreground',
        isGated && 'opacity-60',
      )}
      onClick={handleClick}
      aria-current={isActive ? 'page' : undefined}
    >
      <Icon className="size-4 shrink-0" aria-hidden="true" />
      {item.label}

      {/* Plan badge for gated items */}
      {isGated && item.requiredPlan && item.requiredPlan !== 'solo' && (
        <PlanBadge plan={item.requiredPlan} className="ml-auto" />
      )}

      {/* Count badge */}
      {showCountBadge && (
        <span className="ml-auto inline-flex min-w-[20px] items-center justify-center rounded-full bg-muted px-1.5 py-0.5 text-[10px] font-semibold tabular-nums text-muted-foreground">
          {formatCount(dynamicCount)}
        </span>
      )}

      {/* Dot badge */}
      {showDotBadge && (
        <span className="ml-auto flex h-2 w-2 shrink-0 rounded-full bg-destructive" aria-label="Alert" />
      )}

      {/* New badge */}
      {showNewBadge && (
        <span className="ml-auto inline-flex items-center rounded-sm border border-emerald-500/30 bg-emerald-500/10 px-1.5 py-0.5 text-[9px] font-semibold uppercase tracking-wide text-emerald-600 dark:text-emerald-400">
          NEW
        </span>
      )}
    </button>
  )
}

export function MobileNav({
  userName,
  userEmail,
  userAvatarUrl,
  studioName,
  studioSlug,
  role,
  locationCount,
  permissionKeys,
  plan = 'solo',
  dynamicBadges = {},
  onSignOut,
  open: externalOpen,
  onOpenChange: externalOnOpenChange,
  allMemberships,
  currentStudioId,
  currentLocationId,
  allLocations,
}: MobileNavProps) {
  const [internalOpen, setInternalOpen] = useState(false)
  const open = externalOpen !== undefined ? externalOpen : internalOpen
  const setOpen = useCallback((v: boolean) => {
    setInternalOpen(v)
    externalOnOpenChange?.(v)
  }, [externalOnOpenChange])
  const pathname = usePathname()

  const permissions = useMemo(() => new Set(permissionKeys), [permissionKeys])
  const navGroups = useMemo(() => {
    return APP_NAV
      .filter((group) => !(group.condition === 'multi-location' && locationCount <= 1))
      .map((group) => ({
        ...group,
        items: group.items.filter((item) => {
          if (!item.requiredRoles.includes(role)) return false
          if (item.requiredPermission && !permissions.has(item.requiredPermission)) return false
          return true
        }),
      }))
      .filter((group) => group.items.length > 0)
  }, [role, locationCount, permissions])

  useEffect(() => {
    setOpen(false)
  }, [pathname, setOpen])

  const showStudioSwitcher = allMemberships.length >= 2
  const showLocationSwitcher = allLocations.length >= 2

  return (
    <>
      <Button
        variant="ghost"
        className="flex h-11 w-11 items-center justify-center md:hidden"
        aria-label="Open navigation"
        aria-expanded={open}
        aria-controls="mobile-nav-sheet"
        onClick={() => setOpen(true)}
      >
        <Menu className="size-4" aria-hidden="true" />
      </Button>

      <Sheet open={open} onOpenChange={setOpen}>
        <SheetContent
          id="mobile-nav-sheet"
          side="left"
          className="w-[280px] p-0 flex flex-col"
          showCloseButton={false}
        >
          <div className="flex items-center gap-3 border-b border-border/60 px-4 py-4">
            <Avatar className="h-9 w-9 rounded-full ring-1 ring-border/60 shrink-0">
              {userAvatarUrl && <AvatarImage src={userAvatarUrl} alt={userName} />}
              <AvatarFallback className="rounded-full bg-gradient-to-br from-primary/20 to-primary/10 text-[11px] font-semibold text-primary">
                {getInitials(userName)}
              </AvatarFallback>
            </Avatar>
            <div className="min-w-0 flex-1">
              <p className="truncate text-[13px] font-semibold leading-tight text-foreground">{userName}</p>
              <p className="truncate text-[11px] text-muted-foreground">{studioName}</p>
              <p className="truncate text-[10px] text-muted-foreground/60">{userEmail}</p>
            </div>
            <Button
              variant="ghost"
              className="h-8 w-8 shrink-0"
              onClick={() => setOpen(false)}
              aria-label="Close navigation"
            >
              <X className="size-4" aria-hidden="true" />
            </Button>
          </div>

          {/* Booking link widget in sheet header */}
          {studioSlug && (
            <div className="border-b border-border/60 px-3 py-2">
              <BookingLinkWidget studioSlug={studioSlug} className="mx-0" />
            </div>
          )}

          {(showStudioSwitcher || showLocationSwitcher) && (
            <div className="border-b border-border/60 px-3 py-2 space-y-1">
              {showStudioSwitcher && (
                <div className="flex items-center gap-2 min-h-[44px] px-1">
