import { NextResponse } from 'next/server'
import { z } from 'zod'
import { createClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'

const BodySchema = z.object({
  feature: z.string().min(1).max(64),
})

/**
 * POST /api/feature-interest
 *
 * Records feature interest for coming-soon features.
 * Best-effort insert — silently no-ops if the `feature_interest` table doesn't
 * exist yet (created in a post-S17 migration by Dato).
 *
 * Used by /messages and /portfolio coming-soon pages.
 */
export async function POST(req: Request) {
  try {
    const json: unknown = await req.json()
    const parsed = BodySchema.safeParse(json)
    if (!parsed.success) {
      return NextResponse.json({ error: 'Invalid request' }, { status: 400 })
    }

    const supabase = await createClient()
    const {
      data: { user },
    } = await supabase.auth.getUser()

    if (!user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    // Best-effort insert using raw query approach to avoid TypeScript schema errors
    // for a table that may not exist in the generated types yet.
    // The table `feature_interest` is created by Dato in a future migration.
    const { error } = await supabase.rpc('record_feature_interest', {
      p_feature: parsed.data.feature,
      p_user_id: user.id,
    }).maybeSingle()

    if (error) {
      // RPC or table not yet created — log and continue (graceful degradation)
      logger.info(
        { feature: parsed.data.feature, err: error.message },
        'feature-interest: insert skipped (RPC/table may not exist yet)',
      )
    }

    return NextResponse.json({ ok: true })
  } catch (err) {
    logger.error({ err }, 'feature-interest: unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

